    h = kz_add_own(h, kz_str("    KzList* l = res.as.list;\n"));
    h = kz_add_own(h, kz_str("    if (la) { memcpy(l->items, a.as.list->items, la * sizeof(KzValue)); l->len += la; }\n"));
