    h = kz_add_own(h, kz_str("KZ_MAYBE_UNUSED static inline KzValue kz_not(KzValue a) { return kz_bool(!kz_is_truthy(a)); }\n\n"));
    h = kz_add_own(h, kz_str("KZ_MAYBE_UNUSED static inline bool kz_val_eq(KzValue a, KzValue b) {\n"));
