/* --- Hook driver --- */
static int kz_ticks(int argc, char** argv) {
    for (int i = 1; i + 1 < argc; i++) {
        if (strcmp(argv[i], "--ticks") == 0) { long n = strtol(argv[i + 1], NULL, 10); if (n > 0) return (int)n; }
    }
    const char* env = getenv("KAZE_TICKS");
    if (env && env[0]) { long n = strtol(env, NULL, 10); if (n > 0) return (int)n; }
    return 0;
}
static void kz_run_hooks(int argc, char** argv) {
    int ticks = kz_ticks(argc, argv);
    for (int t = 0; t < ticks; t++) {
    }
}

/* --- Main Entry Point --- */
int main(int argc, char** argv) {
    /* One arena for the whole run; KAZE_ARENA_BYTES overrides the default. */
    if (!kaze_arena_init_heap(&kz_arena, kz_arena_bytes())) { fprintf(stderr, "E_KAZE_OOM: cannot reserve the arena\n"); return 70; }
    atexit(kz_print_alloc_sites);   /* KAZE_ARENA_STATS=1 reports by function */
    KzValue arg_0 = kz_param("", "mode", "main", kz_resolve_cli_arg(argc, argv, "mode", 0));
    KzValue arg_1 = kz_param("", "src", "main", kz_resolve_cli_arg(argc, argv, "src", 1));
    KzValue res = kaze_fn__kz_main(arg_0, arg_1);
    if (res.kind == KZ_VAL_NUM) {
        char numbuf[64];
        kz_format_number(numbuf, sizeof numbuf, res.as.number);
        printf("%s\n", numbuf);
    } else if (res.kind == KZ_VAL_STR) {
        printf("%s\n", res.as.str.data ? res.as.str.data : "");
    } else if (res.kind == KZ_VAL_BOOL) {
        printf("%s\n", res.as.boolean ? "true" : "false");
    }
    kz_run_hooks(argc, argv);
    return 0;
}

